  // a "leap" to the final target or at the end or beginning of a trace when
  // we're wrapping up
  for (const pt of getPortPointsFromNodeWithPortPoints(nodeWithPortPoints)) {
    if (pt.x < bounds.minX) {
      bounds.minX = pt.x
    }
    if (pt.x > bounds.maxX) {
      bounds.maxX = pt.x
    }
    if (pt.y < bounds.minY) {
      bounds.minY = pt.y
    }
    if (pt.y > bounds.maxY) {
      bounds.maxY = pt.y
    }
  }

  return bounds
}
